        debounced2(); // second call - should cancel the first
        console.log('Test 2: second call cancelled first');
    }, 50);

    // Wait for the first timer to fire (if not cancelled)
    setTimeout(() => {
        console.log('Test 3: all tests passed');
    }, 200);
}

